#!/usr/bin/env python3
"""Assemble presentation/index.html from presentation/parts/*.html.

Each part file holds a sequence of <section class="slide"> elements. Run from
anywhere: python3 presentation/tools/build.py
"""
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
HEAD = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Uncertified DAG consensus, machine-checked</title>
<link rel="stylesheet" href="theme.css">
</head>
<body>
<!-- Generated by presentation/tools/build.py from presentation/parts/. Do not edit. -->
<main class="deck">
"""
TAIL = """</main>
<div class="progress"></div>
<script src="witnesses.js"></script>
<script src="dag.js"></script>
<script src="deck.js"></script>
</body>
</html>
"""


def build(parts, out):
    body = "\n".join(p.read_text() for p in parts)
    out.write_text(HEAD + body + TAIL)


if __name__ == "__main__":
    parts = sorted((ROOT / "parts").glob("*.html"))
    build(parts, ROOT / "index.html")
    print(f"index.html from {len(parts)} parts")
